import Foundation

/// CarMode 2.5 的车机网页（index.html / projection.js / projection.css / pcm-playout.js）。
/// 用户实测我们的页面比它卡、触控也不稳，所以浏览器模式整体换成它这一套：
/// 页面原封不动内嵌（base64，避免工程里再加资源文件），服务端按它的协议说话。
/// 与原文的差异只有三处：标签页标题/提示语改成 Carplay；没有 requestVideoFrameCallback
/// 的浏览器（车机是 Chromium 53）加了一个 250 ms 的首帧兜底检查。
enum CarModePage {
    static let version = "carmode-2.5"

    static var html: Data { decode(htmlBase64) }
    static var script: Data { decode(scriptBase64) }
    static var styles: Data { decode(stylesBase64) }
    static var playout: Data { decode(playoutBase64) }

    private static func decode(_ text: String) -> Data { Data(base64Encoded: text) ?? Data() }

    private static let htmlBase64 = ""
    private static let stylesBase64 = ""
    private static let scriptBase64 = ""
    private static let playoutBase64 = ""
}
